contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need an ERC20 token to act as collateral; use the public collateral() view of the clone.
    // The test invokes requestLoan as msg.sender (this contract). The contract must have approved
    // c to transfer collateral beforehand — but since the checker deploys a fresh c and our test
    // contract is the owner of the clone (set via immutable args), we cannot rely on approvals.
    // Instead we craft the test to only call requestLoan when this contract already has enough
    // collateral balance and has approved c; the test will require that this contract has at least
    // collateral amount before invoking requestLoan by observing token balance via public getter.

    // Note: we may not mint tokens here; but we can still write a general property that if
    // requestLoan succeeds (i.e., does not revert) then the state invariants hold. The function
    // captures success via try/catch and asserts the relation between inputs and post-state.

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        // no precondition on inputs; we only reason about the case where requestLoan does not revert.
        // Read collateral token for observation.
        ERC20 coll = c.collateral();

        // record balance before from this contract
        uint256 beforeBal = coll.balanceOf(address(this));

        // compute expected collateral required using c.collateralFor view
        uint256 expectedColl;
        // call view to compute expected collateral; safe to call inside require/assert
        expectedColl = c.collateralFor(amount, loanToCollateral);

        // Attempt to call requestLoan and capture revert flag and returned reqID on success
        bool reverted = false;
        uint256 reqID = type(uint256).max;
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 id) {
            reqID = id;
        } catch {
            reverted = true;
        }

        // read balance after attempt
        uint256 afterBal = coll.balanceOf(address(this));

        // If the call reverted then we cannot assume any state change; if it succeeded then
        // the new request at reqID must be active and its amount must equal the input amount,
        // and this contract's collateral balance must have decreased by exactly expectedColl.

        // We assert the general implication: if not reverted then these properties hold.
        // Use a single assert over public observations.
        if (!reverted) {
            // read request via getRequest
            C.Request memory r = c.getRequest(reqID);
            // assert all conditions in one boolean
            assert(r.active && r.amount == amount && beforeBal - afterBal == expectedColl);
        } else {
            // If reverted, we still must reach an assert. In this branch assert a relation
            // that is implied by revert: no change in balance and reqID is unused. We assert
            // that afterBal == beforeBal (i.e., no collateral was taken) — this is observable.
            assert(afterBal == beforeBal);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
