    // Single public entry performing the whole test
    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        ERC20 coll = c.collateral();

        uint256 beforeBal = coll.balanceOf(address(this));

        uint256 expectedColl = c.collateralFor(amount, loanToCollateral);

        bool reverted;
        uint256 reqID;

        // Make the state-changing call as a top-level statement and capture result via try/catch
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
            reqID = type(uint256).max;
        }

        uint256 afterBal = coll.balanceOf(address(this));

        // Exactly one assert covering both cases (success vs revert).
        // If not reverted: the request at reqID must be active and have amount == amount, and balance decreased by expectedColl.
        // If reverted: balance must be unchanged.
        assert((!reverted && reqID < type(uint256).max && c.getRequest(reqID).active && c.getRequest(reqID).amount == amount && beforeBal - afterBal == expectedColl) || (reverted && afterBal == beforeBal));
    }

    receive() external payable {}
}

