contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that for any caller (this contract) and parameters, requestLoan either reverts or results
    // in the contract receiving collateral equal to collateralFor(amount_, loanToCollateral_) and
    // the newly created request is active and matches the parameters stored via getRequest.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "loanToCollateral must be nonzero to avoid div-by-zero");

        // record balance of c before
        uint256 balBefore = address(c).balance;
        uint256 reqCountBefore = c.requests(); // using auto-generated getter for array length

        bool reverted;
        // calling requestLoan: this will attempt to transfer collateral from msg.sender (this contract)
        // to c, so we need to ensure this contract has sufficient balance of the collateral token.
        // However, we cannot mint ERC20 here; thus the call may revert due to token transfer failure.
        // We catch whether it reverted.
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;
        uint256 reqCountAfter = c.requests();

        // If the call reverted, then no state change should have occurred: request count and balance unchanged.
        // If it did not revert, then exactly one new request must have been pushed and it must be active,
        // and the contract's ETH balance must be unchanged (requestLoan transfers ERC20 collateral, not ETH),
        // and the created request must match the input parameters (amount, interest, loanToCollateral, duration).
        if (reverted) {
            assert(reqCountAfter == reqCountBefore && balAfter == balBefore);
        } else {
            // One new request created
            assert(reqCountAfter == reqCountBefore + 1);

            // request stored should be active and match inputs
            C.Request memory r = c.getRequest(reqCountAfter - 1);
            bool matches = (r.amount == amount_) && (r.interest == interest_) && (r.loanToCollateral == loanToCollateral_) && (r.duration == duration_) && (r.active == true);

            // requestLoan does not transfer Ether; So contract ETH balance should be unchanged
            assert(matches && balAfter == balBefore);
        }
    }

    receive() external payable {}
}

