contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry point for the property test
    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(loanToCollateral != 0, "loanToCollateral must be nonzero to avoid div by zero in collateralFor");

        // record contract collateral token and contract balance before
        ERC20 coll = c.collateral();
        uint256 beforeBal = address(coll).balance; // not allowed: tokens balances aren't accessible via address, must use ERC20.balanceOf
        // Correctly observe via public ERC20.balanceOf
        uint256 beforeContractTokenBal = coll.balanceOf(address(c));

        bool reverted;
        uint256 reqID;
        // call requestLoan as this contract (msg.sender for c will be this test contract)
        try c.requestLoan(amount, interest, loanToCollateral, duration) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If it did not revert, we can observe that a new request was pushed at the last index
        // Determine a plausible reqID: requests is a public array so length is accessible via c.requests(uint256)
        // However there is no direct requests.length getter; but getRequest and isActive exist. We can search by binary probing is expensive; instead we check that there exists some req index i where isActive(i)==true and its values match amount,loanToCollateral,duration and owner transferred collateral accordingly.

        // We'll compute expected collateral amount using collateralFor public view
        uint256 expectedCollateral = c.collateralFor(amount, loanToCollateral);

        // Now search over first, say, 8 recent possible indices: since c was freshly deployed, requests length is small; but to be safe we search a bounded window and require that if not reverted then SOME index in 0..31 matches the new request and the contract's token balance increased by expectedCollateral.
        bool foundMatch = false;
        if (!reverted) {
            // read current contract token balance
            uint256 afterContractTokenBal = coll.balanceOf(address(c));

            // the token balance must have increased by exactly expectedCollateral
            bool balOk = (afterContractTokenBal >= beforeContractTokenBal) && (afterContractTokenBal - beforeContractTokenBal == expectedCollateral);

            // search up to 32 indices for a request that matches
            for (uint256 i = 0; i < 32; i++) {
                // getRequest is public
                try c.getRequest(i) returns (C.Request memory r) {
                    // We cannot refer to C.Request type directly here (it's defined in C), but the returned tuple will be decoded to the individual components if we call the view with multiple return values.
                } catch {
                    // if out of bounds, getRequest will revert; ignore
                }

                // Call getRequest via low-level staticcall to decode fields
                (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("getRequest(uint256)", i));
                if (!ok) continue;
                // decode Request: (uint256 amount,uint256 interest,uint256 loanToCollateral,uint256 duration,bool active)
                (uint256 a, uint256 inr, uint256 ltc, uint256 dur, bool active) = abi.decode(ret, (uint256,uint256,uint256,uint256,bool));
                if (active && a == amount && ltc == loanToCollateral && dur == duration && inr == interest) {
                    foundMatch = true;
                    break;
                }
            }

            // final assert: if call did not revert then both a matching active request exists and token balance increased exactly by expectedCollateral
            assert(balOk && foundMatch);
        } else {
            // if reverted, we assert nothing about state change — but must still assert a general relation: when reverted, expectedCollateral is zero OR the contract token balance did not increase by expectedCollateral
            uint256 afterContractTokenBal2 = coll.balanceOf(address(c));
            bool notIncreasedByExpected = !(afterContractTokenBal2 >= beforeContractTokenBal && afterContractTokenBal2 - beforeContractTokenBal == expectedCollateral);
            assert(notIncreasedByExpected);
        }
    }

    receive() external payable {}
}

