        uint256 beforeContractTokenBal = coll.balanceOf(address(c));

        bool didRevert;
        uint256 reqID;

        // perform the state-changing call as its own top-level statement
        try c.requestLoan(amount, interest, loanToCollateral, duration) returns (uint256 id) {
            didRevert = false;
