        assert((!didRevert && afterContractTokenBal >= beforeContractTokenBal && afterContractTokenBal - beforeContractTokenBal == expectedCollateral && foundMatch) || (didRevert && !(afterContractTokenBal >= beforeContractTokenBal && afterContractTokenBal - beforeContractTokenBal == expectedCollateral)));
    }

    receive() external payable {}
}

