contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount_, interest_, loanToCollateral_, duration_
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "avoid div by zero in collateralFor");

        // ensure this contract has enough collateral tokens to approve and transferFrom
        // We observe only via public surface; we will act as msg.sender when calling c.requestLoan.
        // Precondition: we must have enough collateral token balance; but we cannot mint here.
        // However, the checker deploys a fresh C and this contract is the caller, so we'll attempt the call
        // and record whether it reverted. We then assert that if it succeeded, the contract's balance increased by collateralFor.

        // Read before-values
        uint256 beforeBal = address(c).balance; // irrelevant for ERC20, but allowed to read

        // Call and record revert
        bool reverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call succeeded, then a new request was pushed and is active, and collateral transferFrom must have been performed.
        // We can observe the request via getRequest(reqID) only if we know reqID. The contract pushes at end of requests array, so reqID = get length -1.
        // Use try to read requests length via getRequest in a safe way: we instead call isActive on the last index candidate.

        // Compute expected collateral amount using c.collateral().decimals() via view calls
        // Note: collateral() returns ERC20, we can query decimals() on it.
        ERC20 coll = c.collateral();
        uint8 dec = coll.decimals();

        // compute expected collateralFor = (amount_ * (10 ** dec)) / loanToCollateral_
        // Avoid overflow: use uint256 pow loop
        uint256 tenPow = 1;
        for (uint8 i = 0; i < dec; i++) {
            tenPow *= 10;
        }
        uint256 expectedColl = (amount_ * tenPow) / loanToCollateral_;

        // Determine whether a new request exists and is active: try reading getRequest at index 0.. using length unknown.
        // We can't read requests.length directly (it's public, but named requests and has getter). Actually requests is public so getter requests(uint256) exists, but no length. We can probe an index and see if call reverts.
        bool foundActive;
        // We'll try index 0 first, then iterate a few indices to find an active request created by this call.
        // Limit iterations to small constant to satisfy static analysis.
        for (uint256 i = 0; i < 8; i++) {
            try c.getRequest(i) returns (C.Request memory r) {
                // If the call succeeded, check if this request matches inputs: amount and loanToCollateral and duration and interest
                if (!reverted && r.amount == amount_ && r.loanToCollateral == loanToCollateral_ && r.duration == duration_ && r.interest == interest_ && r.active) {
                    foundActive = true;
                }
            } catch {
                // ignore
            }
        }

        // Now assert the general rule: if requestLoan did not revert, then there exists an active request matching the inputs
        // and the expected collateral is > 0 implies the contract (c) must hold at least expectedColl in collateral token balance.
        // Observe collateral token balance via balanceOf(c)
        uint256 collBal = coll.balanceOf(address(c));

        assert(reverted || (foundActive && (expectedColl == 0 || collBal >= expectedColl)));
    }

    receive() external payable {}
}

