    // params: req amount/interest/loanToCollateral/duration and flags for repayDirect and isCallback
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        // Preconditions: loanToCollateral_ != 0 to avoid div-by-zero in collateralFor
        require(loanToCollateral_ != 0);

        // 1) As msg.sender, create a request by calling requestLoan. This is a top-level state-changing call.
        bool reqReverted;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        // If request creation reverted, we cannot proceed to clear; assert will allow that case.

        // 2) If request succeeded, attempt to clear the request by calling clearRequest from THIS contract (as msg.sender = this)
        // But clearRequest expects to be called by a lender; so we call clearRequest as this contract acting as lender.
        // We need to pick a reqID to clear. The contract pushes requests sequentially starting at 0; since this is a fresh c and we made at most one request, the request should be at index 0.

        bool clearReverted;
        uint256 loanID;
        if (!reqReverted) {
            try c.clearRequest(0, repayDirect_, isCallback_) returns (uint256 id) {
                clearReverted = false;
                loanID = id;
            } catch {
                clearReverted = true;
            }
        } else {
            clearReverted = true;
        }

        // Observations via public surface:
        // - The lender of the created loan should be msg.sender (this contract) when clearRequest succeeds.
        // - clearRequest transfers req.amount of debt() from lender (this contract) to owner (owner() of c). So owner's debt token balance should increase by at most amount_ (exact amount unless token fee-on-transfer), and lender's balance should decrease by that amount.

        // Read debt token and balances via public view functions
        ERC20 debtToken = c.debt();
        address ownerAddr = c.owner();
        uint256 ownerBal = debtToken.balanceOf(ownerAddr);
        uint256 lenderBal = debtToken.balanceOf(address(this));

        // We cannot know balances before the call now because we made state-changing calls; but we can re-check loan data if created.
        bool loanExists = false;
        C.Loan memory loanData;
        if (!clearReverted) {
            // try to read the loan created at loanID
            try c.getLoan(loanID) returns (C.Loan memory L) {
                loanExists = true;
                loanData = L;
            } catch {
                loanExists = false;
            }
        }

        // General property asserted:
        // If clearRequest succeeded (did not revert) then:
        //  - a loan exists with lender == address(this);
        //  - the loan.amount is at least the original request amount (since interest >= 0 may increase it);
        //  - the owner's debt token balance is >= 0 and (ideally) increased by no more than loan.amount, but observable monotonic transfer: owner's balance should be >= 0 and lender's balance should be <= previous (unknown) -- since we cannot read previous, we assert that when loan exists, loan.lender == address(this) and loan.request.amount == amount_ and loan.amount >= amount_.
        // This avoids needing exact balance deltas while still capturing that clearRequest created a loan funded for at least amount_.

        assert(reqReverted || (!clearReverted && loanExists && loanData.lender == address(this) && loanData.request.amount == amount_ && loanData.amount >= amount_));
    }

    receive() external payable {}
}

