        // v == (amount * rate * duration) / (365 days) / 1e18
        // To avoid fractional reordering, assert the multiplication form:
        assert(v * 1e18 == (amount * rate * duration) / 365 days);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Check the multiplicative relation of interestFor with DECIMALS_INTEREST = 1e18
    function run(uint256 amount, uint256 rate, uint256 duration) public payable {
        // keep duration within a year to avoid extremely large products and keep semantics meaningful
        require(duration <= 365 days);
        // avoid overflow for amount * rate * duration when multiplied together
        // ensure amount * rate * duration fits in uint256
        require(rate == 0 || duration == 0 || amount <= type(uint256).max / rate / duration);

        uint256 v = c.interestFor(amount, rate, duration);

        // DECIMALS_INTEREST constant in C is 1e18. Assert the identity:
        // v * 1e18 == (amount * rate * duration) / 365 days
        assert(v * 1e18 == (amount * rate * duration) / 365 days);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters that will be forwarded to requestLoan.
    // The test assumes msg.sender when calling c is this contract (true in checker);
    // so we simulate a caller by directly invoking c.requestLoan from here.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        require(loanToCollateral_ != 0, "avoid div0 in collateralFor");

        // Record number of requests before
        uint256 beforeLen = c.requestsLength();
        // record contract collateral token address to observe balances via its public ERC20 functions
        ERC20 coll = c.collateral();

        // record balance of this contract and of c for collateral token
        uint256 beforeThisBal = coll.balanceOf(address(this));
        uint256 beforeCbal = coll.balanceOf(address(c));

        bool reverted;
        uint256 reqID;
        // perform the mutating call and capture whether it reverts
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            reverted = false;
            reqID = id;
        } catch {
            reverted = true;
        }

        // After-call observations
        uint256 afterLen = c.requestsLength();
        uint256 afterThisBal = coll.balanceOf(address(this));
        uint256 afterCbal = coll.balanceOf(address(c));

        // If the call did not revert, then:
        // - requests length increased by 1
        // - the new request at reqID is active and has same fields
        // - collateral was transferred from this contract to c equal to c.collateralFor(amount_, loanToCollateral_)
        // If it reverted, lengths and balances unchanged.
        if (!reverted) {
            C.Request memory r = c.getRequest(reqID);
            uint256 expectedColl = c.collateralFor(amount_, loanToCollateral_);
            assert(afterLen == beforeLen + 1
                && r.active == true
                && r.amount == amount_
                && r.interest == interest_
                && r.loanToCollateral == loanToCollateral_
                && r.duration == duration_
                && beforeThisBal - afterThisBal == expectedColl
                && afterCbal - beforeCbal == expectedColl
            );
        } else {
            assert(afterLen == beforeLen && afterThisBal == beforeThisBal && afterCbal == beforeCbal);
        }
    }

    // helpers to call public array length getters via the autogenerated functions
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters forwarded to requestLoan. This contract is msg.sender for calls to c.
    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public payable {
        // avoid division by zero in collateralFor
        require(loanToCollateral_ != 0, "loanToCollateral nonzero");

        // Observe number of requests before by reading length via public getter: requests(uint256) exists, so probe until revert to find length.
        // But simpler: call getRequest on index 0..N-1 isn't possible without length. Instead, we can observe that pushing increases the returned getRequest for the new index (requests length is number of existing successful getRequest indices).
        // We'll infer beforeLen by probing sequentially until getRequest reverts; but view functions don't revert when out-of-bounds for public array — they do revert. We'll implement a loop with try/catch to count.
        uint256 beforeLen = 0;
        // cap probing to avoid infinite loops in verifier environment
        for (uint256 i = 0; i < 50; i++) {
            try c.getRequest(i) returns (C.Request memory) {
                beforeLen++;
            } catch {
                break;
            }
        }

        // Observe collateral token and balances
        ERC20 coll = c.collateral();
        uint256 beforeThisBal = coll.balanceOf(address(this));
        uint256 beforeCbal = coll.balanceOf(address(c));

        bool reverted;
        uint256 retReqID = type(uint256).max;
        // perform the mutating call and capture whether it reverts
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 id) {
            reverted = false;
            retReqID = id;
        } catch {
            reverted = true;
        }

        // After-call observations
        uint256 afterLen = 0;
        for (uint256 i = 0; i < 50; i++) {
            try c.getRequest(i) returns (C.Request memory) {
                afterLen++;
            } catch {
                break;
            }
        }

        uint256 afterThisBal = coll.balanceOf(address(this));
        uint256 afterCbal = coll.balanceOf(address(c));

        // Expected collateral transfer amount according to contract view
        uint256 expectedColl = c.collateralFor(amount_, loanToCollateral_);

        // General rule expressed as single assert:
        // If call reverted: lengths and balances unchanged.
        // If succeeded: afterLen == beforeLen + 1, returned reqID equals beforeLen, the stored request at that index matches inputs and is active, and balances changed by expectedColl.
        if (reverted) {
            assert(afterLen == beforeLen
                && afterThisBal == beforeThisBal
                && afterCbal == beforeCbal
            );
        } else {
            // fetch the request that should have been appended
            C.Request memory r = c.getRequest(retReqID);
            assert(
                // length grew by exactly one
                afterLen == beforeLen + 1
                // returned index equals previous length
                && retReqID == beforeLen
                // request stored matches inputs
                && r.active == true
                && r.amount == amount_
                && r.interest == interest_
                && r.loanToCollateral == loanToCollateral_
                && r.duration == duration_
                // collateral balances moved exactly expectedColl from this to c
                && beforeThisBal - afterThisBal == expectedColl
                && afterCbal - beforeCbal == expectedColl
            );
        }
    }

    receive() external payable {}
}
